    private sealed class DelayedAuthenticator : IAuthenticator
    {
        public string GetHost() => "";

        public Dictionary<string, string> GetAuthHeaders() => [];

        public async Task<Dictionary<string, string>> GetAuthHeadersAsync()
        {
            await Task.Delay(20).ConfigureAwait(false);
            return [];
        }
    }

    private static string TraceparentOf(Activity activity) =>
        $"00-{activity.TraceId}-{activity.SpanId}-{(int)activity.ActivityTraceFlags:x2}";

    private static ActivityListener RecordAllActivities()
    {
        var listener = new ActivityListener
        {
            ShouldListenTo = _ => true,
            Sample = (ref ActivityCreationOptions<ActivityContext> _) =>
                ActivitySamplingResult.AllDataAndRecorded,
        };
        ActivitySource.AddActivityListener(listener);
        return listener;
    }

    private static async Task<Dictionary<string, string>> CallCapturingHeadersAsync(
        IAuthenticator? auth = null
    )
    {
        var client = new CapturingApiClient();
        var api = new TestableApi(client, "http://localhost", auth);
        await api.CallAsync<JsonNode>(
            "GET",
            "/test/echo",
            new Dictionary<string, object?>(),
            new Dictionary<string, string>(),
            null,
            ["application/json"],
            "application/json"
        );
        return client.CapturedHeaders;
    }

    [Fact]
    public async Task BhvTracing013AnOperationSendsTheTraceparentOfTheActiveSpan()
    {
        using var listener = RecordAllActivities();
        using var source = new ActivitySource("test.base.api.caller");
        using var activity = source.StartActivity("caller");
        Assert.NotNull(activity);

        var headers = await CallCapturingHeadersAsync();

        Assert.Equal(TraceparentOf(activity), headers["traceparent"]);
    }

    [Fact]
    public async Task BhvTracing014TheSpanStillReachesTraceparentWhenTheCredentialsAreAwaitedFirst()
    {
        using var listener = RecordAllActivities();
        using var source = new ActivitySource("test.base.api.awaited");
        using var activity = source.StartActivity("caller");
        Assert.NotNull(activity);

        var headers = await CallCapturingHeadersAsync(new DelayedAuthenticator());

        Assert.Equal(TraceparentOf(activity), headers["traceparent"]);
    }

    [Fact]
    public async Task BhvTracing015ConcurrentOperationsEachSendTheirOwnCallersTraceparent()
    {
        using var listener = RecordAllActivities();
        using var source = new ActivitySource("test.base.api.concurrent");

        async Task<(string Expected, string? Actual)> RunAsync(string name)
        {
            using var activity = source.StartActivity(name);
            Assert.NotNull(activity);
            var headers = await CallCapturingHeadersAsync(new DelayedAuthenticator());
            return (TraceparentOf(activity), headers.GetValueOrDefault("traceparent"));
        }

        var results = await Task.WhenAll(
            Task.Run(() => RunAsync("first")),
            Task.Run(() => RunAsync("second"))
        );

        Assert.NotEqual(results[0].Expected, results[1].Expected);
        Assert.Equal(results[0].Expected, results[0].Actual);
        Assert.Equal(results[1].Expected, results[1].Actual);
    }

    [Fact]
    public async Task BhvTracing016AnOperationWithNoActiveSpanSendsNoTraceparent()
    {
        using var listener = RecordAllActivities();
        using var source = new ActivitySource("test.base.api.stale");
        using (var activity = source.StartActivity("earlier"))
        {
            Assert.NotNull(activity);
            var traced = await CallCapturingHeadersAsync();
            Assert.True(traced.ContainsKey("traceparent"));
        }
        Activity.Current = null;

        var headers = await CallCapturingHeadersAsync();

        Assert.False(headers.ContainsKey("traceparent"));
    }

